import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Inter');

// Load standard Google Font at module level to guarantee availability
const { fontFamily } = loadFont();



export type FunnelAnimationProps = Record<string, any>;

const FunnelAnimation: React.FC<FunnelAnimationProps> = ({
  backgroundColor = "#0A0A12",
  transparentBackground = false,
  durationInSeconds = 10,
  ownerLabel = "Owner",
  leadershipLabel = "Leadership",
  frictionLabel = "Friction",
  exceptionLabel = "Exceptions",
  ownerColor = "#3B82F6",
  leadershipColor = "#F59E0B",
  frictionColor = "#9CA3AF",
  exceptionColor = "#EF4444",
  filterColor = "#4B5563",
  frictionCount = 60,
  exceptionCount = 6,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const totalFrames = fps * durationInSeconds;

  // Safe background color handling for Remotion parser
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Key Canvas Layout Coordinates
  const ownerX = width * 0.5;
  const ownerY = height * 0.85;
  const leadershipX = width * 0.5;
  const leadershipY = height * 0.15;
  const filterY = height * 0.5;

  const renderFrictionDots = () => {
    return Array.from({ length: frictionCount }).map((_, i) => {
      const lifespan = fps * 2.5; // 2.5 seconds per dot
      const launchWindow = Math.max(1, totalFrames - lifespan);
      const delay = random(`f-delay-${i}`) * launchWindow;
      const t = Math.max(0, Math.min(1, (frame - delay) / lifespan));

      if (t === 0 || t === 1) return null; // Cull offscreen

      // Drift physics for scattering
      const hitDrift = (random(`f-hit-${i}`) * 2 - 1) * (width * 0.15);
      const finalDrift = (random(`f-final-${i}`) * 2 - 1) * (width * 0.25);

      // X trajectory smoothly moves outward
      const x = interpolate(
        t,
        [0, 0.5, 1],
        [ownerX, ownerX + hitDrift, ownerX + finalDrift]
      );

      // Y trajectory bounces off the filter
      let y;
      if (t <= 0.5) {
        y = interpolate(t * 2, [0, 1], [ownerY, filterY], {
          easing: Easing.out(Easing.quad),
        });
      } else {
        y = interpolate((t - 0.5) * 2, [0, 1], [filterY, ownerY], {
          easing: Easing.in(Easing.quad),
        });
      }

      const opacity = interpolate(t, [0, 0.1, 0.9, 1], [0, 1, 1, 0]);

      return (
        <circle
          key={`f-${i}`}
          cx={x}
          cy={y}
          r={width * 0.005}
          fill={frictionColor}
          opacity={opacity}
          style={{ transition: "none" }}
        />
      );
    });
  };

  const renderExceptionDots = () => {
    return Array.from({ length: exceptionCount }).map((_, i) => {
      const lifespan = fps * 3.5; // Exceptions take longer to float up
      const launchWindow = Math.max(1, totalFrames - lifespan);
      const delay = random(`e-delay-${i}`) * launchWindow;
      const t = Math.max(0, Math.min(1, (frame - delay) / lifespan));

      if (t === 0 || t === 1) return null; // Cull offscreen

      const targetDrift = (random(`e-drift-${i}`) * 2 - 1) * (width * 0.1);
      
      const x = interpolate(t, [0, 1], [ownerX, leadershipX + targetDrift]);

      // Hesitation near the filter to simulate passing through
      const y = interpolate(
        t,
        [0, 0.4, 0.6, 1],
        [ownerY, filterY + 25, filterY - 25, leadershipY],
        {
          extrapolateRight: "clamp",
        }
      );

      const opacity = interpolate(t, [0, 0.1, 0.9, 1], [0, 1, 1, 0]);

      return (
        <circle
          key={`e-${i}`}
          cx={x}
          cy={y}
          r={width * 0.012}
          fill={exceptionColor}
          opacity={opacity}
          style={{ transition: "none", filter: "drop-shadow(0px 0px 8px rgba(239, 68, 68, 0.6))" }}
        />
      );
    });
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily,
        color: "#ffffff",
      }}
    >
      {/* Background SVG Canvas for Paths & Dots */}
      <svg
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          overflow: "visible",
        }}
      >
        {/* Filter Line */}
        <line
          x1={width * 0.15}
          y1={filterY}
          x2={width * 0.85}
          y2={filterY}
          stroke={filterColor}
          strokeWidth={4}
          strokeDasharray="16 16"
          strokeLinecap="round"
          opacity={0.6}
          style={{ transition: "none" }}
        />

        {/* Dynamic Dots */}
        {renderFrictionDots()}
        {renderExceptionDots()}
      </svg>

      {/* HTML DOM Overlay for Text & Complex Icons */}
      <AbsoluteFill>
        
        {/* Leadership Node (Top) */}
        <div
          style={{
            position: "absolute",
            top: leadershipY - 100, // Offset to center above the coordinate
            left: "50%",
            transform: "translateX(-50%)",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: "12px",
          }}
        >
          <div
            style={{
              width: 96,
              height: 96,
              borderRadius: "50%",
              backgroundColor: `${leadershipColor}20`,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              border: `2px solid ${leadershipColor}50`,
              boxShadow: `0 0 40px ${leadershipColor}30`,
            }}
          >
            <svg
              width="48"
              height="48"
              viewBox="0 0 24 24"
              fill="none"
              stroke={leadershipColor}
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="M2 4l3 12h14l3-12-6 7-4-7-4 7-6-7zm3 16h14" />
            </svg>
          </div>
          <span
            style={{
              fontSize: 28,
              fontWeight: 600,
              letterSpacing: "0.05em",
              color: leadershipColor,
              textTransform: "uppercase",
            }}
          >
            {leadershipLabel}
          </span>
        </div>

        {/* Owner Node (Bottom) */}
        <div
          style={{
            position: "absolute",
            top: ownerY, 
            left: "50%",
            transform: "translateX(-50%)",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: "12px",
          }}
        >
          <div
            style={{
              width: 96,
              height: 96,
              borderRadius: "50%",
              backgroundColor: `${ownerColor}20`,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              border: `2px solid ${ownerColor}50`,
              boxShadow: `0 0 40px ${ownerColor}30`,
            }}
          >
            <svg
              width="48"
              height="48"
              viewBox="0 0 24 24"
              fill="none"
              stroke={ownerColor}
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2" />
              <circle cx="12" cy="7" r="4" />
            </svg>
          </div>
          <span
            style={{
              fontSize: 28,
              fontWeight: 600,
              letterSpacing: "0.05em",
              color: ownerColor,
              textTransform: "uppercase",
            }}
          >
            {ownerLabel}
          </span>
        </div>

        {/* Legend Box */}
        <div
          style={{
            position: "absolute",
            top: filterY - 45, // Center against the filter line
            left: width * 0.08,
            display: "flex",
            flexDirection: "column",
            gap: "24px",
            backgroundColor: "rgba(20, 20, 28, 0.7)",
            padding: "24px 32px",
            borderRadius: "16px",
            border: "1px solid rgba(255,255,255,0.1)",
            backdropFilter: "blur(12px)",
          }}
        >
          {/* Exceptions Legend */}
          <div style={{ display: "flex", alignItems: "center", gap: "16px" }}>
            <div
              style={{
                width: 24,
                height: 24,
                borderRadius: "50%",
                backgroundColor: exceptionColor,
                boxShadow: `0 0 16px ${exceptionColor}80`,
              }}
            />
            <span style={{ fontSize: 24, fontWeight: 500, color: "#F3F4F6" }}>
              {exceptionLabel}
            </span>
          </div>
          
          {/* Friction Legend */}
          <div style={{ display: "flex", alignItems: "center", gap: "16px" }}>
            <div
              style={{
                width: 14,
                height: 14,
                borderRadius: "50%",
                backgroundColor: frictionColor,
                marginLeft: 5, // Optically align with the larger red dot
              }}
            />
            <span style={{ fontSize: 24, fontWeight: 500, color: "#D1D5DB" }}>
              {frictionLabel}
            </span>
          </div>
        </div>

      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default FunnelAnimation;